def shortest_path(edges, start, end):
    import heapq

    # Handle the case where start and end are the same node
    if start == end:
        return (0, [start])

    # Validate edges and check for negative weights
    graph = {}
    all_nodes = set()

    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative weight edge is not allowed")

        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # Check whether both start and end nodes are present
    if start not in all_nodes or end not in all_nodes:
        return (None, None)

    # If start node has no outgoing edges, check direct equality to end
    if not graph.get(start):
        return (None, None)

    # Initialize distances and previous nodes for path reconstruction
    distances = {node: float('inf') for node in all_nodes}
    distances[start] = 0
    previous = {}

    priority_queue = [(0, start)]
    visited = set()

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # Skip if we've already found a shorter path to this node
        if current_node in visited:
            continue

        visited.add(current_node)

        # If we reached the destination
        if current_node == end:
            # Reconstruct the path
            path = []
            node = current_node
            while node is not None:
                path.append(node)
                node = previous.get(node)
            path.reverse()
            return (current_distance, path)

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if neighbor not in visited and distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous[neighbor] = current_node
                    heapq.heappush(priority_queue, (distance, neighbor))

    # End node is unreachable
    return (None, None)
